<?php $reportLabels=['open'=>'Mới gửi','investigating'=>'Đang xử lý','resolved'=>'Đã giải quyết','dismissed'=>'Không chấp nhận']; ?>
<section class="page-section"><div class="container narrow"><div class="section-title"><h1><?= e($title) ?></h1><a class="btn btn-ghost" href="<?= e(url($adminMode?'/admin':'/bookings')) ?>">Quay lại</a></div>
<?php if(!$adminMode && $targetTitle): ?><form class="surface-card mb-4" method="post" action="<?= e(url('/reports')) ?>"><?= csrf_field() ?><h2 class="h5"><?= e($targetTitle) ?></h2><input type="hidden" name="listing_id" value="<?= (int)$listingId ?>"><input type="hidden" name="booking_id" value="<?= $bookingId?(int)$bookingId:'' ?>"><label for="report-category">Loại vấn đề</label><select id="report-category" class="form-control mb-3" name="category"><?php foreach(['misleading'=>'Thông tin sai sự thật','fraud'=>'Nghi ngờ lừa đảo','complaint'=>'Khiếu nại','other'=>'Khác'] as $value=>$label): ?><option value="<?= $value ?>" <?= ($old['category']??'misleading')===$value?'selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select><label for="report-description">Nội dung (10–5000 ký tự)</label><textarea class="form-control mb-3" id="report-description" name="description" minlength="10" maxlength="5000" required><?= e($old['description']??'') ?></textarea><button class="btn btn-primary">Gửi báo cáo</button></form><?php endif; ?>
<?php if(!$reports): ?><div class="empty-state"><h2>Chưa có báo cáo</h2><p><?= $adminMode?'Báo cáo của khách sẽ xuất hiện ở đây.':'Để gửi báo cáo, mở chi tiết chỗ ở hoặc booking và chọn Báo cáo/Khiếu nại.' ?></p></div><?php endif; ?>
<?php foreach($reports as $report): ?><article class="surface-card mb-3"><h2 class="h5">#<?= (int)$report['id'] ?> · <?= e($report['title']) ?></h2><p><?= e($reportLabels[$report['status']]) ?> · <?= e($report['category']) ?> · <?= e($report['created_at']) ?></p><p><?= nl2br(e($report['description'])) ?></p><?php if($report['resolution']): ?><p><strong>Kết quả:</strong> <?= e($report['resolution']) ?></p><?php endif; ?>
<?php if($adminMode): ?><p>Người gửi: <?= e($report['reporter_name']) ?></p><form method="post" action="<?= e(url('/admin/reports/'.$report['id'].'/resolve')) ?>"><?= csrf_field() ?><label for="report-status-<?= (int)$report['id'] ?>">Trạng thái</label><select class="form-control mb-2" id="report-status-<?= (int)$report['id'] ?>" name="status"><?php foreach($reportLabels as $value=>$label): ?><option value="<?= $value ?>" <?= $value===$report['status']?'selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select><label for="resolution-<?= (int)$report['id'] ?>">Kết luận (bắt buộc khi đóng)</label><textarea class="form-control mb-2" id="resolution-<?= (int)$report['id'] ?>" name="resolution" maxlength="5000"><?= e($report['resolution']) ?></textarea><button class="btn btn-primary">Lưu xử lý</button></form><?php endif; ?>
</article><?php endforeach; ?></div></section>
